const GOALS={
 health:{label:'Gesund & fit',short:'Allround',desc:'Eine gute Mischung aus Kraft, Ausdauer und Beweglichkeit.',rest:'45–90 Sek. Pause',effort:'Meist 2–4 Wiederholungen Reserve'},
 aesthetic:{label:'Look good naked · Muskelaufbau',short:'Muskelaufbau',desc:'Muskelaufbau und eine stärkere Silhouette, ohne ein einzelnes Körperteil zu vernachlässigen.',rest:'60–120 Sek. Pause',effort:'Meist 1–3 Wiederholungen Reserve'},
 strength:{label:'Strength · Maximalkraft',short:'Kraft',desc:'Belastung langsam steigern, technische Qualität und längere Satzpausen.',rest:'120–180 Sek. Pause',effort:'Meist 2–3 Wiederholungen Reserve'},
 muscular:{label:'Kraftausdauer',short:'Kraftausdauer',desc:'Mehr kontrollierte Wiederholungen oder längere Belastungsphasen.',rest:'30–60 Sek. Pause',effort:'Belastend, aber saubere Ausführung'},
 cardio:{label:'Cardio · Ausdauer',short:'Ausdauer',desc:'Kreislaufbelastung über Minuten und Intervallzeiten steuern, nicht über Kilogramm.',rest:'Nach Atemgefühl / Intervallen',effort:'Meist im Gesprächstempo starten'},
 core:{label:'Core · Stabilität',short:'Core',desc:'Rumpfspannung, Anti-Rotation und kontrollierte Bewegung.',rest:'30–60 Sek. Pause',effort:'Haltung vor längerer Haltezeit'},
 mobility:{label:'Mobility · Beweglichkeit',short:'Mobilität',desc:'Beweglichkeit ruhig, kontrolliert und schmerzfrei verbessern.',rest:'Nach Bedarf',effort:'Schmerzfreie Bewegung ohne Zwang'},
 athletic:{label:'Athletik · Funktion',short:'Athletik',desc:'Kraft, Koordination und eine belastbare Grundfitness verbinden.',rest:'60–90 Sek. Pause',effort:'Bewegungsqualität und Kontrolle'}
};
const holdIds=new Set(['plank','sideplank','wall','hollow','pronecobra','bearhold']);
const meta={};
for(const x of EXERCISE_DATA){
 if(catalog[x.id])throw Error('Duplizierte Übung '+x.id);
 catalog[x.id]={name:x.name,target:x.target,muscles:x.muscles,tip:x.tip,easy:x.easy,hard:x.hard,link:'',equipment:x.equipment,kind:x.kind};
 meta[x.id]={equipment:x.equipment,kind:x.kind,base:x.target};
}
const V26_MEDIA={"hexbpress":"Dumbbell_Bench_Press","hexbentrow":"One-Arm_Dumbbell_Row","hexshoulderpress":"Dumbbell_Shoulder_Press","barbsquat":"Barbell_Squat","barbdeadlift":"Barbell_Deadlift","legpress":"Leg_Press","legextension":"Leg_Extensions","latmachine":"Wide-Grip_Lat_Pulldown","rowmachine":"Seated_Cable_Rows","chestmachine":"Machine_Bench_Press","tricepsmachine":"Triceps_Pushdown"};
const oldPhotoSource=photoSrc;
photoSrc=function(id,step=0){const dir=V26_MEDIA[id];return dir?'media/exercises/'+dir+'/'+step+'.jpg?v=26':oldPhotoSource(id,step)};
const originalMeta={
 squat:'strength',bridge:'strength',lunge:'strength',deadbug:'strength',pushup:'strength',snow:'strength',hinge:'strength',sideplank:'hold',plank:'hold',calf:'strength',bird:'strength',wall:'hold',superman:'strength',pike:'strength',diamond:'strength',split:'strength',sidestep:'strength',singlebridge:'strength',heeltoe:'strength',heeltilt:'strength',hollow:'hold',wallpush:'strength',wallslide:'mobility',pronecobra:'hold',bearhold:'hold'
};
for(const [id,x] of Object.entries(catalog))if(!meta[id])meta[id]={equipment:'body',kind:originalMeta[id]||'strength',base:x.target};
const oldMetric=setMetric;
setMetric=function(id){const kind=meta[id]?.kind;if(kind==='cardio')return 'Min.';if(kind==='hold')return 'Sek.';return oldMetric(id)};
const prefRecord='__form_v26_settings';
const preferences=()=>{const raw=records[prefRecord];return {goal:GOALS[raw?.goal]?raw.goal:'health',equipment:Array.isArray(raw?.equipment)&&raw.equipment.length?raw.equipment.filter(x=>EQUIPMENT[x]):['body'],seriesGoals:raw?.seriesGoals&&typeof raw.seriesGoals==='object'?raw.seriesGoals:{}}};
function updatePrefs(change){records[prefRecord]={...preferences(),...change};save()}
function activeSeriesForDate(date){
 let raw;try{raw=JSON.parse(localStorage.getItem('form-calendar-v20')||'null')}catch{return null}
 if(!raw||!Array.isArray(raw.series))return null;
 const elapsed=(start,end)=>Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000);
 for(const rule of raw.series){
  if(rule.type!=='strength'||date<rule.startsOn||rule.endsOn&&date>rule.endsOn||raw.skips?.[rule.id+'|'+date])continue;
  const freq=rule.freq||'weekly',n=Math.max(1,Number(rule.interval)||1),days=elapsed(rule.startsOn,date);
  if(days<0)continue;
  if(freq==='weekly'&&days%(7*n)===0)return rule;
  if(freq==='daily'&&days%n===0)return rule;
  if(freq==='monthly'){
   const a=new Date(rule.startsOn+'T12:00:00'),b=new Date(date+'T12:00:00');
   const months=(b.getFullYear()-a.getFullYear())*12+b.getMonth()-a.getMonth();
   if(months>=0&&months%n===0&&a.getDate()===b.getDate())return rule;
  }
 }
 return null;
}
function selectedGoal(){
 const daily=entry(state.index)?.goalV26;if(GOALS[daily])return daily;
 const series=activeSeriesForDate(iso(state.index));
 const ruleGoal=preferences().seriesGoals?.[series?.id];
 return GOALS[ruleGoal]?ruleGoal:preferences().goal;
}
function randomGoal(){const rs=activeRandom();return GOALS[rs?.goalV26]?rs.goalV26:GOALS[state.randomGoalV26]?state.randomGoalV26:preferences().goal}
function profileFor(id,goal,sessionCount=2,sessionDuration=null,exerciseCount=1){
 const x=catalog[id]||{},kind=meta[id]?.kind||'strength';
 const hold=kind==='hold';const cardio=kind==='cardio';const mobility=kind==='mobility';
 const base=x.target||'8–12';
 let reps=base,sets=sessionCount,rest=GOALS[goal]?.rest||GOALS.health.rest,why='',unit=setMetric(id);
 if(cardio){const block=sessionDuration?Math.max(2,Math.floor((sessionDuration-2)/Math.max(1,exerciseCount))):null;reps=block?`${block}–${block+1} Min.`:goal==='cardio'?'8–20 Min.':'3–8 Min.';sets=1;why='Für Ausdauer zählt die Belastungsdauer und Intensität, nicht die Wiederholungszahl.'}
 else if(mobility){reps=base;sets=1;why='Kontrollierte, schmerzfreie Bewegung und Atmung sind wichtiger als hohe Wiederholungszahlen.'}
 else if(hold){reps=goal==='muscular'?'30–60 Sek.':goal==='strength'?'10–25 Sek.':goal==='mobility'?'20–40 Sek.':'15–40 Sek.';sets=Math.min(3,sessionCount);why='Halte die Position nur so lange wie deine Körperhaltung stabil bleibt.'}
 else if(goal==='strength'){reps='4–8';sets=Math.max(2,Math.min(4,sessionCount));why='Bei Körpergewichtsübungen die Variante erschweren, statt willkürliche Kilogramm vorzugeben.'}
 else if(goal==='aesthetic'){reps='8–15';sets=Math.max(2,Math.min(4,sessionCount));why='Muskelaufbau gelingt mit progressiv schwierigeren Sätzen und genügend Wochenvolumen.'}
 else if(goal==='muscular'){reps='15–25';sets=Math.max(2,Math.min(3,sessionCount));why='Kraftausdauer betont längere Sätze bei kontrollierter Bewegung.'}
 else if(goal==='cardio'){reps='10–18';sets=2;why='Kraftübungen ergänzen das Ausdauertraining; sie ersetzen keine längere Kreislaufbelastung.'}
 else if(goal==='core'){reps='8–12 je Seite';sets=2;why='Priorität hat stabile Rumpfspannung bei jeder Wiederholung.'}
 else if(goal==='mobility'){reps='6–12';sets=1;why='Bewege dich kontrolliert durch den verfügbaren Bewegungsradius.'}
 else if(goal==='athletic'){reps='6–12';sets=Math.max(2,Math.min(3,sessionCount));why='Konzentriere dich auf Bewegungskontrolle und stabile Belastung.'}
 else {reps=base;sets=Math.max(1,Math.min(3,sessionCount));why='Ein flexibler Richtwert; passe ihn an deine Erfahrung an.'}
 return {reps,sets,rest,why,unit,kind,goal:GOALS[goal]?.label||GOALS.health.label};
}
function goalOptions(selected){return Object.entries(GOALS).map(([id,g])=>`<option value="${id}" ${selected===id?'selected':''}>${esc(g.label)}</option>`).join('')}
function equipmentOptions(selected){return Object.entries(EQUIPMENT).map(([id,label])=>`<label class="v26-equipment"><input type="checkbox" data-v26-equipment="${id}" ${selected.includes(id)?'checked':''}><span>${esc(label)}</span></label>`).join('')}
function readOnlyArchive(){return !!entry(state.index).complete}
// Shared catalog is the single source for ordinary sessions and generated sessions.
let libraryQuery='',libraryMuscle='all',libraryKind='all',libraryEquip='all',librarySelection=null;
const MUSCLE_FILTERS={all:'Alle',legs:'Beine',glutes:'Gesäß',abs:'Core',back:'Rücken',chest:'Brust',shoulders:'Schultern',arms:'Arme'};
const KIND_FILTERS={all:'Alle Bewegungen',strength:'Kraft',hold:'Halten',cardio:'Cardio',mobility:'Mobilität'};
function matching(){
 const q=libraryQuery.trim().toLocaleLowerCase('de');
 return Object.entries(catalog).filter(([id,ex])=>{
 const m=meta[id];return (!q||(ex.name+' '+ex.tip+' '+MUSCLE_FILTERS[ex.muscles?.[0]]).toLocaleLowerCase('de').includes(q))&&(libraryMuscle==='all'||ex.muscles?.includes(libraryMuscle))&&(libraryKind==='all'||m.kind===libraryKind)&&(libraryEquip==='all'||m.equipment===libraryEquip);
 }).sort(([a,x],[b,y])=>{const p=preferences().equipment;const pa=p.includes(meta[a].equipment)?0:1,pb=p.includes(meta[b].equipment)?0:1;return pa-pb||x.name.localeCompare(y.name,'de')});
}
function libraryCards(){const arr=matching();return `<div class="v26-library-count">${arr.length} von ${Object.keys(catalog).length} Übungen · Fotos nur bei exakt passender Zuordnung</div><div class="v26-library-grid">${arr.map(([id,ex])=>`<button class="v26-library-card" data-v26-preview="${id}"><span class="v26-icon" aria-hidden="true">${photoSrc(id)?`<img src="${photoSrc(id)}" loading="lazy" alt="" onerror="this.parentElement.textContent='◎'">`:'◎'}</span><span class="v26-library-info"><b>${esc(ex.name)}</b><small>${esc((ex.muscles||[]).map(m=>muscleNames[m]||m).join(' · '))}</small><small>${esc(EQUIPMENT[meta[id].equipment])} · ${meta[id].kind==='cardio'?'Dauer':setMetric(id)} · ${esc(ex.target||'')}</small></span><span class="v26-chevron">›</span></button>`).join('')}</div>`}
function libraryPage(){
 const selected=librarySelection&&catalog[librarySelection];const p=preferences();const goal=state.libraryFrom==='randomizer'?randomGoal():state.libraryFrom==='training'?selectedGoal():p.goal;
 return `<div class="v26-page"><div class="v26-top"><button data-v26-back aria-label="Zurück">‹</button><div><small>FORM. / BIBLIOTHEK</small><h1>${selected?esc(selected.name):'Übungen entdecken'}</h1></div></div>
 ${selected?`<div class="v26-selected"><div class="v26-tags"><span>${esc(EQUIPMENT[meta[librarySelection].equipment])}</span><span>${esc((selected.muscles||[]).map(m=>muscleNames[m]||m).join(' · '))}</span></div>
 <section class="v26-recommendation"><small>TRAININGSRICHTWERT · ${esc(GOALS[goal].short)}</small><b>${esc(profileFor(librarySelection,goal).reps)} · ${profileFor(librarySelection,goal).sets} Sätze</b><p>${esc(profileFor(librarySelection,goal).why)}</p></section>
 <h3>Ausführung</h3><p>${esc(selected.tip)}</p><div class="v26-tips"><p><b>Leichter:</b> ${esc(selected.easy)}</p><p><b>Schwerer:</b> ${esc(selected.hard)}</p></div>
 <div class="v26-actions">${state.libraryFrom==='randomizer'||state.libraryFrom==='training'?`<button data-v26-add="${librarySelection}" class="v26-primary">＋ Zum Training hinzufügen</button>`:'<button data-v26-go-training class="v26-primary">Zum Trainingsbereich</button>'}<button data-v26-all class="v26-soft">Andere Übung wählen</button></div></div>`:
 `<p class="v26-intro">Wähle aus ${Object.keys(catalog).length} Übungen, nach Muskelgruppe, Equipment und Bewegungsart.</p><label class="v26-search">Übung suchen<input id="v26-search" type="search" autocomplete="off" placeholder="z. B. Rudern, Glute Bridge, Beinpresse" value="${esc(libraryQuery)}"></label>
 <div class="v26-filter-row"><label>Muskelgruppe<select data-v26-muscle>${Object.entries(MUSCLE_FILTERS).map(([id,t])=>`<option value="${id}" ${libraryMuscle===id?'selected':''}>${esc(t)}</option>`).join('')}</select></label>
 <label>Equipment<select data-v26-equip>${Object.entries({all:'Alle Geräte',...EQUIPMENT}).map(([id,t])=>`<option value="${id}" ${libraryEquip===id?'selected':''}>${esc(t)}</option>`).join('')}</select></label>
 <label>Art<select data-v26-kind>${Object.entries(KIND_FILTERS).map(([id,t])=>`<option value="${id}" ${libraryKind===id?'selected':''}>${esc(t)}</option>`).join('')}</select></label></div>
 <div id="v26-library-results">${libraryCards()}</div>`}</div>`;
}
function openLibrary(from){state.libraryFrom=from||state.view;state.view='library';librarySelection=null;render();window.scrollTo(0,0)}
function renderLibrary(){
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='body'));
 const root=document.querySelector('#root');if(!root)return;root.innerHTML=libraryPage();
 root.querySelector('[data-v26-back]')?.addEventListener('click',()=>{if(librarySelection){librarySelection=null;render()}else{setView(state.libraryFrom==='randomizer'?'randomizer':state.libraryFrom==='training'?'training':state.libraryFrom==='home'?'home':'body')}});
 root.querySelector('[data-v26-all]')?.addEventListener('click',()=>{librarySelection=null;render()});
 root.querySelector('[data-v26-go-training]')?.addEventListener('click',()=>setView('training'));
 root.querySelectorAll('[data-v26-preview]').forEach(b=>b.addEventListener('click',()=>{librarySelection=b.dataset.v26Preview;render();window.scrollTo(0,0)}));
 root.querySelectorAll('[data-v26-add]').forEach(b=>b.addEventListener('click',()=>{
  const id=b.dataset.v26Add;if(!catalog[id])return;
  if(state.libraryFrom==='randomizer'&&activeRandom()){
   const rs=activeRandom();if(rs.completed){alert('Abgeschlossenes Training zuerst wieder öffnen.');return}
   if(rs.exercises.some(x=>x.id===id)&&!confirm('Die Übung ist bereits im Plan. Trotzdem erneut hinzufügen?'))return;
   const n=profileFor(id,randomGoal(),rs.duration<=15?1:rs.duration<=25?2:3).sets;
   modifyRandom(s=>s.exercises.push({id,variant:'standard',sets:Array(n).fill(null),weights:Array(n).fill(null),done:[]}));state.randomStage='plan';state.addingToRandom=false;setView('randomizer');
  }else if(state.libraryFrom==='training'){
   if(readOnlyArchive()){alert('Training erst wieder öffnen, um es zu bearbeiten.');return}
   const a=clone(list(state.index));const n=profileFor(id,selectedGoal(),2).sets;
   a.push({id,variant:'standard',sets:Array(n).fill(null),weights:Array(n).fill(null),done:[]});updatePlan(state.index,a);setView('training');
  }
 }));
 const q=root.querySelector('#v26-search');if(q)q.addEventListener('input',()=>{const pos=q.selectionStart;libraryQuery=q.value;root.querySelector('#v26-library-results').innerHTML=libraryCards();root.querySelectorAll('[data-v26-preview]').forEach(b=>b.addEventListener('click',()=>{librarySelection=b.dataset.v26Preview;render();window.scrollTo(0,0)}));q.focus();q.setSelectionRange(pos,pos)});
 for(const [name,setter] of [['muscle',v=>libraryMuscle=v],['equip',v=>libraryEquip=v],['kind',v=>libraryKind=v]]){root.querySelector(`[data-v26-${name}]`)?.addEventListener('change',e=>{setter(e.target.value);render()})}
 setStatus();
}
// New recommended workout content matches goals and available equipment.
const baseBuildRandom=buildRandomSession;
function goalCompatible(goal,k){return goal==='cardio'?k==='cardio'||k==='strength':goal==='mobility'?k==='mobility'||k==='hold':goal==='core'?k==='hold'||k==='strength':k==='strength'||k==='hold'}
function focusMatch(focus,muscles){if(focus==='all')return true;const groups=focus==='legs'||focus==='lower'?['legs','glutes']:focus==='abs'?['abs']:['back','chest','arms','shoulders'];return (muscles||[]).some(x=>groups.includes(x))}
function chooseExercise(pool,picked,goal){
 const used=new Set(picked.map(id=>movement[id]||meta[id]?.kind+'-'+catalog[id]?.muscles?.[0]));
 const ranked=pool.filter(id=>!picked.includes(id)).map(id=>{
  const x=catalog[id],kind=meta[id].kind;let weight=1;
  const move=movement[id]||kind+'-'+x.muscles[0];if(used.has(move))weight*=0.42;
  if(goal==='cardio'&&kind==='cardio')weight*=4;
  if(goal==='mobility'&&kind==='mobility')weight*=4;
  if(goal==='core'&&x.muscles.includes('abs'))weight*=3;
  if(meta[id].equipment==='body')weight*=1.15;
  if(goal==='strength'&&kind==='strength')weight*=3;
  return {id,score:weight*Math.random()};
 });
 if(!ranked.length)return null;
 ranked.sort((a,b)=>b.score-a.score);
 const shortlist=ranked.slice(0,Math.min(8,ranked.length));return shortlist[Math.floor(Math.random()*shortlist.length)].id;
}
buildRandomSession=function(){
 const goal=GOALS[state.randomGoalV26]?state.randomGoalV26:preferences().goal;
 const prefs=preferences();const focus=state.randomFocus||'all';const duration=Number(state.randomDuration)||20;
 const count=Math.max(3,Math.min(8,Number(state.randomCount)||5));
 let pool=Object.keys(catalog).filter(id=>prefs.equipment.includes(meta[id].equipment)&&focusMatch(focus,catalog[id].muscles)&&goalCompatible(goal,meta[id].kind));
 if(goal==='cardio'&&focus!=='all'&&!pool.some(id=>meta[id].kind==='cardio'))pool=Object.keys(catalog).filter(id=>prefs.equipment.includes(meta[id].equipment)&&goalCompatible(goal,meta[id].kind));
 if(!pool.length){alert('Für diese Ziel- und Equipment-Kombination gibt es noch keine passenden Übungen. Aktiviere unter „Dein Ziel“ weitere Geräte oder wähle einen anderen Fokus.');return}
 const selected=[];const capped=duration<=10?Math.min(count,4):duration<=15?Math.min(count,5):count;
 while(selected.length<capped){const n=chooseExercise(pool,selected,goal);if(!n)break;selected.push(n)}
 const baseSets=duration<=15?1:duration<=25?2:3;
 const items=selected.map(id=>{const p=profileFor(id,goal,baseSets,duration,selected.length);return {id,variant:state.randomDifficulty==='easy'?'easy':state.randomDifficulty==='hard'?'hard':'standard',sets:Array(p.sets).fill(null),weights:Array(p.sets).fill(null),done:[]}});
 const rs={id:'r-'+Date.now()+'-'+Math.floor(Math.random()*1e6),date:nowIso(),createdAt:new Date().toISOString(),focus,duration,goalV26:goal,completed:false,exercises:items};
 randomSessions.push(rs);state.randomActiveId=rs.id;state.randomStage='plan';saveRandom();render();
};
function addSettingsPanel(){
 const p=preferences();
 const root=document.querySelector('#root');if(!root)return;
 if(state.view==='home'){
  const anchor=root.querySelector('.v20-hero,.v20-hero-card,.v20-hero-actions,.hero-session')||root.firstElementChild;
  const node=document.createElement('section');node.className='v26-settings';node.innerHTML=`<div class="v26-settings-title"><div><small>DEIN TRAININGSKOMPASS</small><h2>Was möchtest du erreichen?</h2></div><button data-v26-library-open="home">Übungen entdecken →</button></div><label>Allgemeines Ziel<select data-v26-main-goal>${goalOptions(p.goal)}</select></label><details><summary>Verfügbares Equipment (${p.equipment.length})</summary><div class="v26-equipment-grid">${equipmentOptions(p.equipment)}</div></details><p>${esc(GOALS[p.goal].desc)}</p>`;
  anchor?.before(node);
 } else if(state.view==='training'&&['A','B'].includes(dayType(state.index))){
  const target=root.querySelector('.session-summary,.exercise-list,.v20-workout-panel')||root.firstElementChild;
  const goal=selectedGoal();const node=document.createElement('section');node.className='v26-session-goal';node.innerHTML=`<div><small>ZIEL DIESER EINHEIT</small><select data-v26-session-goal ${readOnlyArchive()?'disabled':''}>${goalOptions(goal)}</select><p>${esc(GOALS[goal].desc)}</p></div><button data-v26-library-open="training" ${readOnlyArchive()?'disabled':''}>＋ Übung suchen</button>`;
  target?.before(node);
  const rule=activeSeriesForDate(iso(state.index));
  if(rule&&!readOnlyArchive()){
    const b=document.createElement('button');b.className='v26-series-goal';b.dataset.v26SeriesGoal=rule.id;
    b.textContent='Ziel auch für diese Terminserie übernehmen';node.append(b);
  }
 } else if(state.view==='randomizer'){
  const rs=activeRandom();const setup=state.randomStage==='setup'||!rs;
  if(setup){
   const target=root.querySelector('.random-block,.random-lead');const goal=GOALS[state.randomGoalV26]?state.randomGoalV26:p.goal;
   const node=document.createElement('section');node.className='v26-random-goal';node.innerHTML=`<small>ZIEL DES ZUFALLSTRAININGS</small><select data-v26-random-goal>${goalOptions(goal)}</select><p>${esc(GOALS[goal].desc)}</p><small>Verfügbares Equipment: ${esc(p.equipment.map(x=>EQUIPMENT[x]).join(', '))}</small>`;
   target?.before(node);
  }else{
   const target=root.querySelector('.v23-workout-top,.v23-detail-heading');
   const goal=randomGoal();const node=document.createElement('div');node.className='v26-plan-goal';node.innerHTML=`Ziel: <strong>${esc(GOALS[goal].short)}</strong> <span>· ${esc(GOALS[goal].rest)}</span>`;
   target?.before(node);
   const cards=root.querySelectorAll('.v23-exercise');cards.forEach((card,i)=>{const x=rs.exercises[i],sub=card.querySelector('.v23-sub');if(x&&sub){const t=profileFor(x.id,goal,x.sets.length,rs.duration,rs.exercises.length);sub.textContent=`${x.sets.length} Sätze · ${t.reps}`}});
  }
 }
 if(state.view==='body'){
  // One consistent, licensed and interactive anatomical atlas. No gender switch or legacy schematic.
  const sex=root.querySelector('.sex-tabs');if(sex)sex.remove();
  const toggle=root.querySelector('.v20-view-toggle');if(toggle){const atlas=toggle.querySelector('[data-atlas-view="atlas"]');if(atlas&&!atlas.classList.contains('active')){atlas.click();return}toggle.remove()}
  const stage=root.querySelector('.body-stage');if(stage)stage.classList.add('v26-one-atlas');
  const heading=root.querySelector('.app-heading');if(heading){const desc=document.createElement('p');desc.className='v26-atlas-caption';desc.textContent='Detaillierter, interaktiver 2D-Muskelatlas · vorne und hinten. Muskelgruppe antippen oder aus der Liste wählen.';heading.after(desc)}
  const target=root.querySelector('.body-section-title');if(target){const b=document.createElement('button');b.className='v26-body-search';b.dataset.v26LibraryOpen='body';b.textContent='Alle '+Object.keys(catalog).length+' Übungen durchsuchen →';target.before(b)}
 }
 if(state.view==='detail'||state.view==='randomizer'&&state.randomStage==='detail'){
  const random=state.view==='randomizer';const rs=random?activeRandom():null;
  const x=random?rs?.exercises?.[Number(state.randomDetailIndex)||0]:list(state.index)?.[state.detailIndex];
  if(x){const goal=random?randomGoal():selectedGoal();const p=profileFor(x.id,goal,x.sets?.length||2,random?rs.duration:null,random?rs.exercises.length:1);
   const pres=root.querySelector('.v24-prescription');
   if(pres){const box=pres.querySelector('.v24-prescription-grid');if(box){const vals=box.querySelectorAll('strong');if(vals[0])vals[0].textContent=String(x.sets?.length||p.sets);if(vals[1])vals[1].textContent=p.reps}
    const heading=pres.querySelector('.v24-overline');if(heading)heading.textContent='EMPFEHLUNG · '+GOALS[goal].short;
    const explain=pres.querySelector('.v24-guidance-note');if(explain)explain.textContent=p.why+' · '+GOALS[goal].rest+' · '+GOALS[goal].effort+'.';
   }
  }
 }
 root.querySelectorAll('[data-v26-library-open]').forEach(b=>b.addEventListener('click',()=>openLibrary(b.dataset.v26LibraryOpen)));
 root.querySelector('[data-v26-main-goal]')?.addEventListener('change',e=>{updatePrefs({goal:e.target.value});state.randomGoalV26=e.target.value;render()});
 root.querySelectorAll('[data-v26-equipment]').forEach(el=>el.addEventListener('change',()=>{const arr=[...root.querySelectorAll('[data-v26-equipment]:checked')].map(x=>x.dataset.v26Equipment);if(!arr.length){el.checked=true;alert('Mindestens eine Equipment-Kategorie muss ausgewählt sein.');return}updatePrefs({equipment:arr});render()}));
 root.querySelector('[data-v26-session-goal]')?.addEventListener('change',e=>{edit(state.index,{goalV26:e.target.value});render()});
 root.querySelector('[data-v26-series-goal]')?.addEventListener('click',e=>{
  const id=e.target.dataset.v26SeriesGoal,goal=selectedGoal();const p=preferences();
  if(!id||!GOALS[goal])return;
  updatePrefs({seriesGoals:{...p.seriesGoals,[id]:goal}});
  render();
  alert('Ziel für weitere Termine dieser Serie gespeichert. Bereits absolvierte Trainings bleiben unverändert.');
 });
 root.querySelector('[data-v26-random-goal]')?.addEventListener('change',e=>{state.randomGoalV26=e.target.value;render()});
}
